source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] == background and (r,c) not in outside:
                outside.add((r,c)); queue.append((r,c))
    while queue:
        r,c = queue.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in outside:
                outside.add((nr,nc)); queue.append((nr,nc))
    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r,c) not in outside:
                result[r][c] = 4
    return result
'''
